package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.trading.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orchestrator/stage8/trading") public class Stage8TradingController {private final ManualMarketDataAdapter market;private final BacktestService backtests;private final PaperRiskOfficerService risk;private final PaperTradingService paper;public Stage8TradingController(ManualMarketDataAdapter market,BacktestService backtests,PaperRiskOfficerService risk,PaperTradingService paper){this.market=market;this.backtests=backtests;this.risk=risk;this.paper=paper;}@PostMapping("/market-data") public MarketDataSnapshot ingest(@RequestBody MarketDataSnapshot s){return market.ingest(s);}@PostMapping("/backtests") public BacktestResultEntity backtest(@RequestBody BacktestRequest r){return backtests.run(r);}@GetMapping("/backtests") public List<BacktestResultEntity> backtests(){return backtests.recent();}@GetMapping("/paper/risk-policy") public PaperRiskPolicyEntity risk(){return risk.policy();}@PutMapping("/paper/risk-policy") public PaperRiskPolicyEntity risk(@RequestBody PaperRiskPolicyRequest r){return risk.update(r);}@GetMapping("/paper/account") public PaperAccountEntity account(){return paper.account();}@PostMapping("/paper/open/{signalId}") public PaperExecutionResult open(@PathVariable UUID signalId){return paper.open(signalId);}@PostMapping("/paper/positions/{positionId}/close") public PaperPositionEntity close(@PathVariable UUID positionId,@RequestParam(defaultValue="0") double price){return paper.close(positionId,price);}@GetMapping("/paper/positions") public List<PaperPositionEntity> positions(){return paper.positions();}@GetMapping("/paper/journal") public List<PaperJournalEntity> journal(){return paper.journal();}}
